def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive.append(o)
        except Exception:
            pass

    # Read yesterday bids from previous_trace
    prev_bids = []
    for o in alive:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the market was
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        max_prev = 0.0
        avg_prev = 0.0

    # Base aggressiveness by my hp
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Supply pressure: higher supply -> less need to overbid
    # Map supply roughly to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # If I am close to running out of hp, bid more.
    urgency = 0.0
    if no_water_days >= 2:
        urgency += 0.35
    if hp <= 2.0:
        urgency += 0.45
    elif hp <= 4.0:
        urgency += 0.25
    elif hp <= 6.0:
        urgency += 0.12

    # Competitive adjustment from yesterday
    # If someone bid very high yesterday, others likely overcommitted; we shade down slightly.
    comp = 0.0
    if prev_bids:
        if max_prev >= DAILY_SALARY * 1.6:
            comp = 0.10
        elif max_prev >= DAILY_SALARY * 1.2:
            comp = 0.18
        else:
            comp = 0.25

    # Core target bid
    # Target around a fraction of DAILY_SALARY; increase with urgency; decrease with supply.
    base = DAILY_SALARY * (0.55 + comp - 0.25 * supply_factor)
    target = base * (1.0 + urgency)

    # If yesterday's max was extremely high, cap our bid to avoid repeating their failure mode.
    if prev_bids and max_prev >= DAILY_SALARY * 1.75:
        target = min(target, DAILY_SALARY * 1.05)

    # Ensure we don't exceed budget
    if budget <= 0.0:
        return 0.0

    # Keep a minimum bid when we must secure water
    min_bid = 0.0
    if no_water_days >= 3 or hp <= 2.0:
        min_bid = DAILY_SALARY * 0.85
    elif hp <= 4.0:
        min_bid = DAILY_SALARY * 0.65

    bid = max(min_bid, target)
    if bid > budget:
        bid = budget

    # Also avoid bidding above a reasonable ceiling in mid/low supply
    # (prevents overpaying when supply is likely enough)
    ceiling = DAILY_SALARY * (1.2 - 0.2 * supply_factor)  # ~96..128
    if bid > ceiling:
        bid = ceiling

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)
